def compute(vars):
    current = vars["v1"]
    prior = vars["v2"]

    if prior == 0:
        return None

    change = current - prior
    growth_rate = change / prior

    return {
        "value": growth_rate,
        "trace": {
            "current_net_revenue": current,
            "prior_net_revenue": prior,
            "change": change,
            "growth_rate": growth_rate,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
